mapper.select:
SELECT id FROM (
    SELECT id
    FROM project
    WHERE biz_no = #{bizNo}
      AND prj_identifier = #{prjIdentifier}
    ORDER BY id DESC
) WHERE ROWNUM = 1

mapper.update:
update project
set prj_hide = 'Y' , closed_date = sysdate
where id = #{id}

 	UPDATE project
	SET prj_hide ='N', updated_on = SYSDATE, prj_identifier = #{prjIdentifier}
	WHERE id = #{id}
	  AND NOT EXISTS (
	    SELECT 1
	    FROM project p2
	    WHERE p2.biz_no = (SELECT biz_no FROM project WHERE id = #{id})
	      AND p2.prj_identifier = #{prjIdentifier}
	      AND p2.id != #{id}
 	 )

mapper.select:
SELECT COUNT(*)
FROM project
WHERE prj_par_id = #{id}
